library xil_defaultlib;
use xil_defaultlib.conv_pkg.all;

library xpm;
use xpm.vcomponents.all;
library IEEE;
use IEEE.std_logic_1164.all;

entity pfb_fft_bitgrowth_xlspram is
   generic(width_addr        : integer := -1;
           width             : integer := -1;
           mem_size          : integer := 0;
           write_mode_a      : string  := "no_change";
           mem_init_file     : string  := "none";
           read_reset_val    : string  := "0";
           mem_type          : string  := "auto";
           init_value        : bit_vector := b"00";
           xpm_lat            : integer := 1;
           latency           : integer := 0);
   port(data_in: in std_logic_vector(width-1 downto 0);
        addr: in std_logic_vector(width_addr-1 downto 0);
        we: in std_logic_vector(0 downto 0);
        en: in std_logic_vector(0 downto 0);
        rst: in std_logic_vector(0 downto 0);
        ce: in std_logic;
        clk: in std_logic;
        data_out: out std_logic_vector(width-1 downto 0)
);

end pfb_fft_bitgrowth_xlspram;

architecture behavior of pfb_fft_bitgrowth_xlspram is
signal a_en: std_logic_vector(0 downto 0);
signal a_we: std_logic_vector(0 downto 0);
signal a_rst: std_logic_vector(0 downto 0);
signal xpm_rst: std_logic_vector(0 downto 0);
signal core_data_out, lat_data_out, dly_data_out: std_logic_vector(width-1 downto 0);

component synth_reg
    generic (
      width: integer;
      latency: integer
    );
    port (
      i: in std_logic_vector(width - 1 downto 0);
      ce: in std_logic;
      clr: in std_logic;
      clk: in std_logic;
      o: out std_logic_vector(width - 1 downto 0)
    );
  end component;

component synth_reg_w_init
  generic (width      : integer;
  init_index : integer;
  init_value : bit_vector;
  latency    : integer);
  port (i   : in std_logic_vector(width-1 downto 0);
  ce  : in std_logic;
  clr : in std_logic;
  clk : in std_logic;
  o   : out std_logic_vector(width-1 downto 0));
end component; -- end synth_reg_w_init

begin
a_en(0) <= en(0) and ce;
a_we(0) <= we(0) and ce;
a_rst(0) <= rst(0) and ce;
data_out <= dly_data_out;

  rst_test: if (latency > 1) generate
     xpm_rst(0) <= '0';
  end generate;
  rst_test_2:if (latency <= 1) generate
     xpm_rst(0) <= rst(0) and ce;
  end generate; 


xpm_memory_spram_inst : xpm_memory_spram

generic map (
   -- Common module generics
     MEMORY_SIZE        => mem_size,        --positive integer
     MEMORY_PRIMITIVE   => mem_type,
     MEMORY_INIT_FILE   => mem_init_file,
     MEMORY_INIT_PARAM  => "",
     USE_MEM_INIT       => 1,
     WAKEUP_TIME        => "disable_sleep",
     MESSAGE_CONTROL    => 0,

     -- Port A module generics
     WRITE_DATA_WIDTH_A => width,
     READ_DATA_WIDTH_A  => width,
     BYTE_WRITE_WIDTH_A => width,
     ADDR_WIDTH_A       => width_addr,
     READ_RESET_VALUE_A => read_reset_val,
     READ_LATENCY_A     => xpm_lat,
     WRITE_MODE_A       => write_mode_a
 )
 port map (
     -- Common module ports
     sleep          =>  '0',
     -- Port A module ports
     clka           =>  clk,
     rsta           =>  xpm_rst(0),
     ena            =>  a_en(0),
     regcea         =>  ce,
	  wea            =>  a_we,
	  addra          =>  addr,
	  dina           =>  data_in,
	  injectsbiterra =>  '0',  --do not change
	  injectdbiterra =>  '0',  --do not change
	  douta          =>  core_data_out,
	  sbiterra       =>  open, --do not change
	  dbiterra       =>  open  --do not change
);

latency_test:if (latency > 2)  generate
  reg1: synth_reg
    generic map (
    width => width,
    latency => latency - 2
    )
    port map (
    i => core_data_out,
    ce => a_en(0),
    clr => '0',
    clk => clk,
    o => lat_data_out
    );
  reg2: synth_reg_w_init
    generic map (width      => width,
    init_index => 2,
    init_value => init_value,
    latency    => 1)
    port map (i   => lat_data_out,
    ce  => a_en(0),
    clr => a_rst(0),
    clk => clk,
    o   => dly_data_out);
  end generate;

  latency_2 : if (latency = 2) generate
  reg3: synth_reg_w_init
    generic map (width      => width,
    init_index => 2,
    init_value => init_value,
    latency    => 1)
    port map (i   => core_data_out,
    ce  => a_en(0),
    clr => a_rst(0),
    clk => clk,
    o   => dly_data_out);
  end generate;

  latency_1 : if (latency<=1) generate
  dly_data_out <= core_data_out;
  end generate;
end behavior;
library xil_defaultlib;
use xil_defaultlib.conv_pkg.all;

